#!/usr/bin/env python3
"""Execute the Thumb generated by the compact Coder/FCoder/Writer fixture."""

import argparse
import struct
import subprocess
from pathlib import Path

from unicorn import Uc, UC_ARCH_ARM, UC_MODE_THUMB
from unicorn.arm_const import UC_ARM_REG_LR, UC_ARM_REG_PC, UC_ARM_REG_R0, UC_ARM_REG_R10, UC_ARM_REG_SP


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("fixture", type=Path)
    parser.add_argument("--image", type=Path, default=Path(__file__).resolve().parents[3]
                        / "app/src/main/jniLibs/armeabi/libjbedvm.so")
    args = parser.parse_args()
    output = subprocess.run([str(args.fixture.resolve()), str(args.image)], check=True,
                            stdout=subprocess.PIPE).stdout
    address, size, expected, rom_base = struct.unpack_from("<IIII", output)
    code = output[16:]
    if len(code) != size:
        raise AssertionError("partial compiler output")
    machine = Uc(UC_ARCH_ARM, UC_MODE_THUMB)
    image = args.image.read_bytes()
    machine.mem_map(rom_base, (len(image) + 4095) & ~4095)
    machine.mem_write(rom_base, image)
    base = address & ~4095
    machine.mem_map(base, (address - base + size + 4095) & ~4095)
    machine.mem_write(address, code)
    stack, stop = 0x200000, 0x400000
    machine.mem_map(stack, 0x10000)
    machine.mem_map(stop, 4096)
    initial_sp = stack + 0xFF00
    machine.reg_write(UC_ARM_REG_SP, initial_sp)
    machine.reg_write(UC_ARM_REG_R10, stack)
    machine.reg_write(UC_ARM_REG_LR, stop | 1)
    machine.emu_start(address | 1, stop, count=1000)
    actual = machine.reg_read(UC_ARM_REG_R0)
    if machine.reg_read(UC_ARM_REG_PC) != stop:
        raise AssertionError("generated method did not return before the instruction budget")
    if actual != expected or machine.reg_read(UC_ARM_REG_SP) != initial_sp:
        raise AssertionError(f"generated method returned {actual}, expected {expected}, or did not restore SP")
    print(f"CLDC class file → Compiler → Thumb: Calc.run() returned {actual}, stack restored ({size} bytes)")


if __name__ == "__main__":
    main()
